// Código para nó de Código no n8n
// Converte ISO date para formato "Dia DD/MM, HH:MM" e gera saudação
// Acessa o valor do campo 'agora' do item atual
const isoDate = $input.item.json.agora;
// Cria objeto Date a partir da string ISO
const date = new Date(isoDate);
// Subtrai 3 horas para ajustar o fuso horário
date.setHours(date.getHours() - 3);
// Extrai dia, mês, hora e minuto
const dia = date.getDate().toString().padStart(2, '0');
const mes = (date.getMonth() + 1).toString().padStart(2, '0'); // +1 porque getMonth() retorna 0-11
const hora = date.getHours().toString().padStart(2, '0');
const minuto = date.getMinutes().toString().padStart(2, '0');
// Formata no padrão desejado
const dataFormatada = `Dia ${dia}/${mes}, ${hora}:${minuto}`;

// Gera saudação baseada na hora
let boasVindas;
const horaNumero = date.getHours();

if (horaNumero >= 5 && horaNumero < 12) {
  boasVindas = "Bom dia";
} else if (horaNumero >= 12 && horaNumero < 17) {
  boasVindas = "Boa tarde";
} else {
  boasVindas = "Boa noite";
}

// Retorna o resultado
return {
  json: {
    dataFormatada: dataFormatada,
    boasVindas: boasVindas
  }
};

// Verifica se items existe e não está vazio
if (!items || items.length === 0 || !items[0].json) {
  return [{ json: { markdown: "" } }];
}

let markdownHistory = "";
for (const item of items) {
  // Verifica se o item tem a estrutura esperada
  if (item?.json?.message) {
    const message = item.json.message;
    const prefix = message.type === "ai" ? "## CADU: " : "## CLIENTE: ";
    markdownHistory += `${prefix}${message.content}\n\n`;
  }
}

return [
  {
    json: {
      markdown: markdownHistory.trim()
    }
  }
];

