// Acessa a string do nó "formataHistorico"
const historico = $node["formataHistorico"].json.markdown || "";

// Lista de saudações que queremos identificar
const saudacoes = ["boa tarde", "bom dia", "boa noite"];

// Verifica se alguma saudação aparece no histórico (ignorando maiúsculas/minúsculas)
const saudacaoEncontrada = saudacoes.some(saudacao =>
  historico.toLowerCase().includes(saudacao)
);

// Retorna um novo objeto com o campo "saudacao"
return [
  {
    json: {
      saudacao: saudacaoEncontrada
    }
  }
];

/**
 * Code node — Run Once for All Items
 * Lê do nó "When Executed by Another Workflow"
 * Emite 1 item por elemento de webhook[], com o conteúdo de .json direto.
 */

const src = $('When Executed by Another Workflow').first().json;

if (!src || !Array.isArray(src.webhook)) {
  throw new Error('Não encontrei array "webhook" no nó "When Executed by Another Workflow".');
}

return src.webhook
  .filter(el => el && el.json && typeof el.json === 'object')
  .map(el => ({ json: el.json }));

